/**
 * Spike 5 T6: instrument classification for S-3 (BD / SD / HH; docs/audio-spike5-plan.md section 2, section 6).
 *
 * Input: T5's detectOnsets() result (one onset per group of simultaneous hits, the 44.1 kHz signal `y`). Output: one
 * AnalysisDrumHit per (onset, instrument present), multi-label, with strength, confidence and `alts` (the next
 * instruments, plan decision 5). No learned model: fixed formulas, hand-set values (config `classify`) and FIXED
 * templates measured from the tuning kit's one-shots (templates.ts, regenerated by make_templates.ts).
 *
 * Steps (each a config switch; T6 kept what helped, see the T6 report):
 *  1. band rules (nmf off): per onset fluxRel[b] = onset flux of band b / T5's band threshold. BD when
 *     fluxRel[low] >= ruleLow; SD when fluxRel[mid] >= ruleMid and fluxRel[mid] / fluxRel[low] >= ruleMidOverLow;
 *     HH when fluxRel[high] >= ruleHigh and fluxRel[high] / fluxRel[mid] >= ruleHighOverMid. None passes -> the band
 *     with the largest fluxRel. strength = amplitude of the band energy (10^(energyDb / 20)).
 *  2. NMF with fixed templates (nmf): mel spectrogram M of |X| (win / hop / melBands over fminHz..fmaxHz). Per onset
 *     the observation x = max(0, mean(M[c + postFrom .. + postCount)) - M[c - preFrames]), c = onset frame of the
 *     refined time (the subtraction removes what was already ringing: cymbal washes, BD tails). x ~ W h with W the
 *     template columns (each sums to 1; BD / SD / HH incl. HO, plus absorbers RD CR toms (nmfOthers), the
 *     S-拡張 sounds CB SD.xs (nmfExt) and RD.bell SP CN (nmfExtCymbals) that are never output), h >= 0 by multiplicative updates (nmfBeta 1 = KL, 2 = Euclidean,
 *     nmfIterations). Class activation a_c = sum of h over its columns (= the L1 mass it explains), share_c =
 *     a_c / sum of all a. Take reference ref_c = refQuantile of a_c over the onsets where c has the largest share and
 *     share >= 0.5 (fewer than refMinHits: the same quantile of all onsets' total). Present when share_c >=
 *     shareMin[c] and 20 log10(a_c / ref_c) >= levelMinDb. None present: the best S-3 class when the S-3 classes hold
 *     at least half of the activations, else nothing (an absorbed cymbal / tom). strength = a_c.
 *  2b. metal split (metalDecay, needs nmf): another kit's closed HH can look like the template kit's RD at the onset,
 *     so the onset spectrum alone does not tell HH from a cymbal; the decay does (plan S-9: cymbals ring long). Per
 *     onset highDecayRates() measures how fast the energy it added above decayFminHz falls (until the next onset, at
 *     most decayMaxMs); at >= hhMinDecayDbPerSec the activations of the metal absorbers (RD CR RD.bell SP CN) count
 *     for HH, else they stay absorbed (a slow open HH still wins with its own HH / HO templates).
 *  3. refit (refit, needs nmf): onsets whose only present class is c with share_c >= refitShare (at least
 *     refitMinHits of them) give one extra column for c = mean of their normalised observations; then step 2 again.
 *  4. HPSS (hpss, needs nmf): the mel spectrogram is replaced by its percussive part (soft mask P^2 / (P^2 + H^2),
 *     H = median over hpssTimeFrames frames, P = median over hpssFreqBins bands) before the observations.
 *  2b' take test (metalTakeFastMin, T10): the split only in a take whose metal-dominated onsets mostly decay fast.
 *  2d. channel EQ (eqRounds, T10): templates times the take's per-band gain (takeEq: observed / fitted), then refit.
 *  5. adapt (T10): per-take templates from the take's own confident hits (adaptColumns), for an unknown kit.
 *  6. tom adapt (T11b, S-9 only, toms.adapt): per-take tom columns from tom-like onsets (tomAdaptedBasis), refit; the
 *     S-3 decisions are those of step 5, only the S-9 evidence comes from this fit.
 *  7. S-ext (T12, level S-ext only): ext.ts extHits rewrites the S-9 hits from the S-9 metal fit's S-拡張 columns and the
 *     tom window's tonal peak.
 * Confidence of class c: share-based, present -> 0.5 .. 1 (0.5 + 0.5 (share - shareMin) / (1 - shareMin)), absent ->
 * 0 .. 0.5 (0.5 share / shareMin, capped below 0.5); rules: the same with fluxRel / rule threshold.
 * `alts` of a hit: the absent S-3 classes by confidence, at most candidatesMax.
 */
import { applyMel, melFilterBank, melFrequencies } from '../dsp/core/mel';
import { medianFilter1d } from '../dsp/core/median';
import { StftFramer } from '../dsp/core/stft';
import { DEFAULT_DRUM_CONFIG, type DrumConfig } from './config';
import type { DrumOnset, OnsetDetection } from './onset';
import { cosToProfile, highDrops, metalLabel, type MetalVotes } from './cymbals';
import { DRUM_TEMPLATES } from './templates';
import { extHits, tonalPeak, type ExtEvidence } from './ext';
import { groupNames, groupPitches, ratioVote, tomFeaturesOf, tomSeeds, TOMS, windowMag, type TomFeatures, type TomInst } from './toms';
import type { AnalysisDrumHit, DrumInst, DrumLevel } from './types';

export const S3_CLASSES = ['BD', 'SD', 'HH'] as const;
export type S3Class = (typeof S3_CLASSES)[number];
/** extFoot (T12): the pedal HH, never in the S-3 / S-9 basis (it absorbed real HH, T6); only S-ext's foot test reads it. */
export type TemplateGroup = S3Class | 'other' | 'ext' | 'extCym' | 'extFoot';

/** The spectrum parameters a template table was built with (must equal the config's to be used). */
export type SpecParams = Pick<DrumConfig['classify'], 'win' | 'hop' | 'melBands' | 'fminHz' | 'fmaxHz' | 'preFrames' | 'postFrom' | 'postCount'> & { sr: number };

export interface TemplateColumn {
  /** Kit instrument of the one-shot. */
  inst: DrumInst;
  group: TemplateGroup;
  velocity: number;
  /** melBands values, sum 1. */
  w: number[];
}
export interface TemplateTable {
  source: string;
  params: SpecParams;
  columns: TemplateColumn[];
}

export function specParams(cfg: DrumConfig): SpecParams {
  const c = cfg.classify;
  return { sr: cfg.audio.sr, win: c.win, hop: c.hop, melBands: c.melBands, fminHz: c.fminHz, fmaxHz: c.fmaxHz, preFrames: c.preFrames, postFrom: c.postFrom, postCount: c.postCount };
}
const sameParams = (a: SpecParams, b: SpecParams) => (Object.keys(a) as (keyof SpecParams)[]).every((k) => a[k] === b[k]);

/* ------------------------------------------------------------------ spectrum */

export interface MelSpec {
  frames: number;
  bands: number;
  /** [frame * bands + m] mel magnitude. */
  data: Float32Array;
}

/** Mel spectrogram of |X| (centred Hann STFT, librosa conventions; slaney mel bank over fminHz..fmaxHz). */
export function melSpectrogram(y: Float32Array, p: SpecParams): MelSpec {
  const fr = new StftFramer(y, { nFft: p.win, hop: p.hop });
  const bank = melFilterBank(p.sr, p.win, p.melBands, p.fminHz, Math.min(p.fmaxHz, p.sr / 2));
  const mag = new Float64Array(fr.bins);
  const out = new Float32Array(p.melBands);
  const data = new Float32Array(fr.frames * p.melBands);
  for (let t = 0; t < fr.frames; t++) {
    fr.frame(t);
    for (let k = 0; k < fr.bins; k++) mag[k] = Math.hypot(fr.re[k], fr.im[k]);
    applyMel(bank, mag, out);
    data.set(out, t * p.melBands);
  }
  return { frames: fr.frames, bands: p.melBands, data };
}

/** Percussive part by median-filter HPSS (soft mask, power 2) on the mel spectrogram. */
export function hpssPercussive(s: MelSpec, timeFrames: number, freqBins: number): MelSpec {
  const { frames, bands, data } = s;
  const H = new Float32Array(data.length);
  const P = new Float32Array(data.length);
  const lane = new Float32Array(frames);
  const laneOut = new Float32Array(frames);
  for (let m = 0; m < bands; m++) {
    for (let t = 0; t < frames; t++) lane[t] = data[t * bands + m];
    medianFilter1d(lane, timeFrames, laneOut);
    for (let t = 0; t < frames; t++) H[t * bands + m] = laneOut[t];
  }
  const col = new Float32Array(bands);
  for (let t = 0; t < frames; t++) {
    medianFilter1d(data.subarray(t * bands, (t + 1) * bands), freqBins, col);
    P.set(col, t * bands);
  }
  const out = new Float32Array(data.length);
  for (let i = 0; i < data.length; i++) {
    const p2 = P[i] * P[i];
    const h2 = H[i] * H[i];
    out[i] = p2 + h2 > 0 ? (data[i] * p2) / (p2 + h2) : 0;
  }
  return { frames, bands, data: out };
}

/** Onset observation (see the file comment, step 2) at time t (s). */
export function observation(s: MelSpec, t: number, p: SpecParams): Float64Array {
  const { bands, frames, data } = s;
  const c = Math.round((t * p.sr) / p.hop);
  const pre = Math.max(0, Math.min(frames - 1, c - p.preFrames));
  const x = new Float64Array(bands);
  let n = 0;
  for (let f = c + p.postFrom; f < c + p.postFrom + p.postCount; f++) {
    if (f < 0 || f >= frames) continue;
    n++;
    for (let m = 0; m < bands; m++) x[m] += data[f * bands + m];
  }
  for (let m = 0; m < bands; m++) x[m] = Math.max(0, (n ? x[m] / n : 0) - data[pre * bands + m]);
  return x;
}

/* ------------------------------------------------------------------ NMF (fixed W) */

/**
 * Activations h >= 0 of x ~ W h, W given as columns (each sums to 1), by multiplicative updates: beta 1 = KL
 * (h_k *= sum_m W_mk x_m / (Wh)_m), beta 2 = Euclidean (h_k *= (W'x)_k / (W'W h)_k). Start: h_k = sum(x) / K.
 */
export function solveActivations(W: readonly ArrayLike<number>[], x: ArrayLike<number>, iterations: number, beta = 1): Float64Array {
  const K = W.length;
  const M = x.length;
  const h = new Float64Array(K);
  let sx = 0;
  for (let m = 0; m < M; m++) sx += x[m];
  if (!(sx > 0) || K === 0) return h;
  h.fill(sx / K);
  const v = new Float64Array(M);
  const eps = 1e-12;
  for (let it = 0; it < iterations; it++) {
    v.fill(0);
    for (let k = 0; k < K; k++) {
      const w = W[k];
      const hk = h[k];
      for (let m = 0; m < M; m++) v[m] += w[m] * hk;
    }
    for (let k = 0; k < K; k++) {
      const w = W[k];
      let num = 0;
      let den = 0;
      for (let m = 0; m < M; m++) {
        if (beta === 1) {
          num += (w[m] * x[m]) / (v[m] + eps);
          den += w[m];
        } else {
          num += w[m] * x[m];
          den += w[m] * v[m];
        }
      }
      h[k] *= num / (den + eps);
    }
  }
  return h;
}

/* ------------------------------------------------------------------ decisions */

export interface OnsetClass {
  t: number;
  /** Per S3_CLASSES: activation (NMF) or fluxRel (rules). */
  a: number[];
  /** Per S3_CLASSES: share of the activations (NMF) or fluxRel / rule threshold (rules). */
  share: number[];
  /** Share of all activations held by the absorbers (NMF). */
  otherShare: number;
  present: boolean[];
  confidence: number[];
  strength: number[];
}

export interface ClassifyResult {
  hits: AnalysisDrumHit[];
  onsets: OnsetClass[];
  /** Template columns used (after refit). */
  columns: number;
  refitAdded: S3Class[];
  /** Classes whose templates the last adapt round replaced / extended (step 5). */
  adapted: S3Class[];
  /** The last NMF fit (nmf only): instrument / group of each column (null inst = adapted column) and h per onset. */
  fit?: { inst: (DrumInst | null)[]; group: TemplateGroup[]; h: Float64Array[] };
  ms: { spec: number; nmf: number; total: number };
}

const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
function presentConf(r: number, min: number): number {
  return 0.5 + 0.5 * clamp01((r - min) / Math.max(1e-9, 1 - min));
}
const absentConf = (r: number, min: number) => Math.min(0.499, 0.5 * clamp01(r / Math.max(1e-9, min)));

function quantileOf(v: number[], q: number): number {
  if (!v.length) return 0;
  const s = [...v].sort((a, b) => a - b);
  const p = q * (s.length - 1);
  const lo = Math.floor(p);
  const hi = Math.min(s.length - 1, lo + 1);
  return s[lo] + (s[hi] - s[lo]) * (p - lo);
}

/** Step 1: band rules on T5's per-band onset flux. */
export function classifyRules(onsets: readonly DrumOnset[], thresholds: readonly number[], cfg: DrumConfig['classify']): OnsetClass[] {
  return onsets.map((o) => {
    const rel = [0, 1, 2].map((b) => o.flux[b] / Math.max(1e-12, thresholds[b]));
    const mins = [cfg.ruleLow, cfg.ruleMid, cfg.ruleHigh];
    const ratioOk = [true, rel[1] >= cfg.ruleMidOverLow * rel[0], rel[2] >= cfg.ruleHighOverMid * rel[1]];
    const present = rel.map((r, b) => r >= mins[b] && ratioOk[b]);
    if (!present.some(Boolean)) present[rel.indexOf(Math.max(...rel))] = true;
    const share = rel.map((r, b) => r / mins[b]);
    const confidence = share.map((s, b) => (present[b] ? presentConf(Math.min(1, s / 4), 0.25) : absentConf(Math.min(s, ratioOk[b] ? s : 0.99), 1)));
    return { t: o.t, a: rel, share, otherShare: 0, present, confidence, strength: o.energyDb.slice(0, 3).map((d) => 10 ** (d / 20)) };
  });
}

/** Cymbal-like absorber instruments: with metalDecay their activation counts for HH on a fast-decaying onset. */
export const METAL_INSTS: readonly DrumInst[] = ['RD', 'CR', 'RD.bell', 'SP', 'CN'];

interface Basis {
  W: ArrayLike<number>[];
  group: TemplateGroup[];
  metal: boolean[];
  /** Kit instrument of the column (null: an adapted column). */
  inst: (DrumInst | null)[];
}

function basisOf(table: TemplateTable, cfg: DrumConfig['classify']): Basis {
  const on: Record<TemplateGroup, boolean> = { BD: true, SD: true, HH: true, other: cfg.nmfOthers, ext: cfg.nmfExt, extCym: cfg.nmfExtCymbals, extFoot: false };
  const cols = table.columns.filter((c) => on[c.group]);
  return { W: cols.map((c) => c.w), group: cols.map((c) => c.group), metal: cols.map((c) => METAL_INSTS.includes(c.inst)), inst: cols.map((c) => c.inst) };
}

interface Act {
  a: number[];
  /** All absorbers, incl. metal. */
  other: number;
  metal: number;
  /** Per basis column. */
  h: Float64Array;
}

function activations(basis: Basis, obs: Float64Array[], cfg: DrumConfig['classify']): Act[] {
  return obs.map((x) => {
    const h = solveActivations(basis.W, x, cfg.nmfIterations, cfg.nmfBeta);
    const a = [0, 0, 0];
    let other = 0;
    let metal = 0;
    h.forEach((v, k) => {
      const g = basis.group[k];
      const ci = (S3_CLASSES as readonly string[]).indexOf(g);
      if (ci >= 0) a[ci] += v;
      else {
        other += v;
        if (basis.metal[k]) metal += v;
      }
    });
    return { a, other, metal, h };
  });
}

/**
 * Step 2b take test (T10): the metal absorbers stand for a closed HH in this take when, of the onsets they dominate
 * (>= half of all activations; at least minHits of them), >= fastMin decay fast. A real ride / crash rings, so a take
 * whose metal onsets ring keeps them absorbed. fastMin 0 = every take (T6's metalDecay).
 */
export function metalTakeIsHh(acts: readonly Pick<Act, 'a' | 'other' | 'metal'>[], fast: readonly boolean[], fastMin: number, minHits: number): boolean {
  if (fastMin <= 0) return true;
  const dom = acts.map((x, i) => ({ x, i })).filter(({ x }) => x.metal >= 0.5 * (x.a[0] + x.a[1] + x.a[2] + x.other) && x.metal > 0);
  if (dom.length < minHits) return false;
  return dom.filter(({ i }) => fast[i]).length >= fastMin * dom.length;
}

/**
 * Step 2d (eqRounds, T10): the take's channel (mic, room, EQ) as a per-band gain G_m = sum_i x_im / sum_i (W h_i)_m
 * (3-band moving average, clamped to +-maxDb), from the current fit of all onsets. Kit- and mic-independent: a phone
 * mic that removes the lows makes every template's lows count less.
 */
export function takeEq(obs: readonly ArrayLike<number>[], W: readonly ArrayLike<number>[], hs: readonly ArrayLike<number>[], maxDb: number): Float64Array {
  const M = obs[0]?.length ?? 0;
  const sx = new Float64Array(M);
  const sr = new Float64Array(M);
  obs.forEach((x, i) => {
    for (let m = 0; m < M; m++) sx[m] += x[m];
    W.forEach((w, k) => {
      const h = hs[i][k];
      if (h > 0) for (let m = 0; m < M; m++) sr[m] += w[m] * h;
    });
  });
  const lim = 10 ** (maxDb / 20);
  const g = new Float64Array(M);
  for (let m = 0; m < M; m++) {
    let a = 0;
    let b = 0;
    for (let j = Math.max(0, m - 1); j <= Math.min(M - 1, m + 1); j++) {
      a += sx[j];
      b += sr[j];
    }
    g[m] = b > 0 && a > 0 ? Math.min(lim, Math.max(1 / lim, a / b)) : 1;
  }
  return g;
}

function equalised(b: Basis, g: ArrayLike<number>): Basis {
  return { ...b, W: b.W.map((w) => normalised(Float64Array.from(w, (v, m) => v * g[m]))) };
}

/** Step 2b (metalDecay): on an onset whose high band decays fast, the metal absorbers' activation is HH's. */
function mergeMetal(acts: Act[], fast: readonly boolean[]): Act[] {
  return acts.map((x, i) => (fast[i] ? { ...x, a: [x.a[0], x.a[1], x.a[2] + x.metal], other: x.other - x.metal, metal: 0 } : x));
}

/**
 * Decay rate (dB/s) of the energy an onset added in the mel bands at or above fminHz: frac = (E[end] - E[pre]) /
 * (E[peak] - E[pre]), peak = max over the onset frame and the next 2, end = the frame before the next onset or
 * peak + maxMs; rate = -10 log10(frac) / (end - peak). Infinity (= fast) when end - peak < minMs or nothing was added.
 */
export function highDecayRates(s: MelSpec, onsets: readonly DrumOnset[], p: SpecParams, o: { fminHz: number; minMs: number; maxMs: number }): number[] {
  const mf = melFrequencies(p.melBands + 2, p.fminHz, Math.min(p.fmaxHz, p.sr / 2));
  const m0 = Math.max(0, mf.findIndex((f, i) => i >= 1 && f >= o.fminHz) - 1);
  const E = new Float64Array(s.frames);
  for (let t = 0; t < s.frames; t++) {
    let e = 0;
    for (let m = m0; m < s.bands; m++) e += s.data[t * s.bands + m];
    E[t] = e;
  }
  const fr = (sec: number) => Math.round((sec * p.sr) / p.hop);
  const frameSec = p.hop / p.sr;
  return onsets.map((on, i) => {
    const c = fr(on.t);
    const pre = E[Math.max(0, c - p.preFrames)];
    let pk = c;
    for (let f = c; f <= Math.min(s.frames - 1, c + 2); f++) if (E[f] > E[pk]) pk = f;
    const next = i + 1 < onsets.length ? fr(onsets[i + 1].t) - 1 : s.frames - 1;
    const end = Math.min(next, pk + Math.round(o.maxMs / 1000 / frameSec), s.frames - 1);
    if ((end - pk) * frameSec * 1000 < o.minMs || !(E[pk] > pre)) return Infinity;
    const frac = Math.min(1, Math.max(1e-6, (E[end] - pre) / (E[pk] - pre)));
    return (-10 * Math.log10(frac)) / ((end - pk) * frameSec);
  });
}

/**
 * T12b: a quiet hi-hat under a loud BD / SD - HH not present by the usual rule, BD or SD present, HH share >=
 * hhCoShare (below shareMin[2]) and HH activation >= hhCoLevelDb re the take's HH reference.
 */
export function hhUnderDrum(present: readonly boolean[], hhShare: number, hhAct: number, hhRef: number, cfg: Pick<DrumConfig['classify'], 'hhCoShare' | 'hhCoLevelDb'>): boolean {
  return !present[2] && (present[0] || present[1]) && hhShare >= cfg.hhCoShare && hhRef > 0 && 20 * Math.log10(Math.max(hhAct, 1e-30) / hhRef) >= cfg.hhCoLevelDb;
}

function decideNmf(onsets: readonly DrumOnset[], acts: Act[], cfg: DrumConfig['classify']): OnsetClass[] {
  const total = acts.map((x) => x.a[0] + x.a[1] + x.a[2] + x.other);
  const shares = acts.map((x, i) => x.a.map((v) => (total[i] > 0 ? v / total[i] : 0)));
  const refs = S3_CLASSES.map((_, c) => {
    const dom = acts.filter((_, i) => shares[i][c] >= 0.5 && shares[i][c] === Math.max(...shares[i])).map((x) => x.a[c]);
    return dom.length >= cfg.refMinHits ? quantileOf(dom, cfg.refQuantile) : quantileOf(total, cfg.refQuantile);
  });
  return onsets.map((o, i) => {
    const { a } = acts[i];
    const share = shares[i];
    const levelOk = a.map((v, c) => refs[c] > 0 && 20 * Math.log10(Math.max(v, 1e-30) / refs[c]) >= cfg.levelMinDb);
    const present = share.map((s, c) => s >= cfg.shareMin[c] && levelOk[c]);
    if (hhUnderDrum(present, share[2], a[2], refs[2], cfg)) present[2] = true;
    const s3 = share[0] + share[1] + share[2];
    if (!present.some(Boolean) && s3 >= 0.5 && total[i] > 0) present[share.indexOf(Math.max(...share))] = true;
    const confidence = share.map((s, c) => (present[c] ? presentConf(s, cfg.shareMin[c]) : levelOk[c] ? absentConf(s, cfg.shareMin[c]) : Math.min(absentConf(s, cfg.shareMin[c]), 0.25)));
    return { t: o.t, a, share, otherShare: total[i] > 0 ? acts[i].other / total[i] : 0, present, confidence, strength: a };
  });
}

function normalised(x: Float64Array): Float64Array {
  let s = 0;
  for (const v of x) s += v;
  return s > 0 ? x.map((v) => v / s) : x;
}

/** Hits of the classified onsets (time order, S-3 class order within an onset). */
export function hitsOf(cls: readonly OnsetClass[], candidatesMax: number): AnalysisDrumHit[] {
  const hits: AnalysisDrumHit[] = [];
  for (const o of cls) {
    const absent = S3_CLASSES.map((inst, c) => ({ inst, c })).filter(({ c }) => !o.present[c]).sort((x, y) => o.confidence[y.c] - o.confidence[x.c]);
    S3_CLASSES.forEach((inst, c) => {
      if (!o.present[c]) return;
      const h: AnalysisDrumHit = { t: o.t, inst, strength: o.strength[c], confidence: o.confidence[c] };
      const alts = absent.slice(0, candidatesMax).map(({ inst: i, c: k }) => ({ inst: i, confidence: o.confidence[k] }));
      if (alts.length) h.alts = alts;
      hits.push(h);
    });
  }
  return hits;
}

/** Mel-band centroid (in band-index units) of an observation; NaN when empty. Only compared within one take. */
export function bandCentroid(x: ArrayLike<number>): number {
  let s = 0;
  let m1 = 0;
  for (let m = 0; m < x.length; m++) {
    s += x[m];
    m1 += m * x[m];
  }
  return s > 0 ? m1 / s : NaN;
}

/**
 * Per class c, the part of observation x that c's columns explain: max(0, x - sum of every other column's w h) (the
 * residual after the rest of the fit; for a single-class onset ~ x). Metal columns count for HH on a `fast` onset.
 * T11 `keep` (per S-3 class, default none): for the HH part only, the columns of a kept class are NOT subtracted - a
 * small share that another kit's hi-hat gives the wrong class (kit D's hi-hat mids taken by kit A's SD) stays in the part.
 */
export function classParts(
  x: ArrayLike<number>,
  W: readonly ArrayLike<number>[],
  group: readonly TemplateGroup[],
  h: ArrayLike<number>,
  metalAsHh: readonly boolean[],
  keep: readonly boolean[] = [false, false, false],
): Float64Array[] {
  return S3_CLASSES.map((cls) => {
    const r = Float64Array.from(x);
    W.forEach((w, k) => {
      const gi = (S3_CLASSES as readonly string[]).indexOf(group[k]);
      if (group[k] === cls || (cls === 'HH' && metalAsHh[k]) || !(h[k] > 0) || (cls === 'HH' && gi >= 0 && keep[gi])) return;
      for (let m = 0; m < r.length; m++) r[m] -= w[m] * h[k];
    });
    for (let m = 0; m < r.length; m++) if (r[m] < 0) r[m] = 0;
    return r;
  });
}

export function cosine(a: ArrayLike<number>, b: ArrayLike<number>): number {
  let ab = 0;
  let aa = 0;
  let bb = 0;
  for (let m = 0; m < a.length; m++) {
    ab += a[m] * b[m];
    aa += a[m] * a[m];
    bb += b[m] * b[m];
  }
  return aa > 0 && bb > 0 ? ab / Math.sqrt(aa * bb) : 0;
}

/** Share of x's mass in bands whose centre is below / at or above hz (centres: melCentres). */
export function massBelow(x: ArrayLike<number>, centres: ArrayLike<number>, hz: number): number {
  let s = 0;
  let lo = 0;
  for (let m = 0; m < x.length; m++) {
    s += x[m];
    if (centres[m] < hz) lo += x[m];
  }
  return s > 0 ? lo / s : 0;
}

export type AdaptCfg = Pick<
  DrumConfig['classify'],
  'adaptKeepCos' | 'adaptShare' | 'adaptMinHits' | 'adaptLowHz' | 'adaptLowMin' | 'adaptHighHz' | 'adaptHighMin'
>;

/**
 * Kit-independent gate of a seed part: BD has >= adaptLowMin of its mass below adaptLowHz; HH has >=
 * adaptHighMin at or above adaptHighHz; SD neither.
 */
export function gateOk(k: number, part: ArrayLike<number>, centres: ArrayLike<number>, cfg: AdaptCfg): boolean {
  const low = massBelow(part, centres, cfg.adaptLowHz);
  const high = 1 - massBelow(part, centres, cfg.adaptHighHz);
  if (k === 0) return low >= cfg.adaptLowMin;
  if (k === 2) return high >= cfg.adaptHighMin;
  return low < cfg.adaptLowMin && high < cfg.adaptHighMin;
}

/**
 * Step 5 (adapt, T10): per-take template adaptation for an unknown kit. Seeds of class c = onsets where c is present
 * with share_c >= adaptShare (HH seeds also need a fast high-band decay: a closed HH, kit-independent),
 * and whose c part (classParts) passes the band gate (gateOk). With >= adaptMinHits seeds, c's template = the mean
 * of the normalised parts. The adapted templates must keep the kit-independent order of their band
 * centroids BD < SD < HH; both classes of a broken pair keep their kit templates this round. A class whose mean part
 * is within cosine adaptKeepCos of one of its own kit columns (kitCols: the known kit) is not adapted.
 */
export function adaptColumns(
  parts: readonly Float64Array[][],
  cls: readonly OnsetClass[],
  fast: readonly boolean[],
  centres: ArrayLike<number>,
  cfg: AdaptCfg,
  kitCols: readonly (readonly ArrayLike<number>[])[] = [[], [], []],
): (Float64Array | null)[] {
  const cols: (Float64Array | null)[] = S3_CLASSES.map((_, k) => {
    const seeds = cls
      .map((_, i) => i)
      .filter((i) => {
        const o = cls[i];
        return o.present[k] && o.share[k] >= cfg.adaptShare && (k !== 2 || fast[i]) && gateOk(k, parts[i][k], centres, cfg);
      });
    if (seeds.length < cfg.adaptMinHits) return null;
    const mean = new Float64Array(parts[0][k].length);
    for (const i of seeds) normalised(parts[i][k]).forEach((v, m) => (mean[m] += v / seeds.length));
    // the kit's own template already fits this take (a known kit): keep it
    if (kitCols[k].some((w) => cosine(w, mean) >= cfg.adaptKeepCos)) return null;
    return normalised(mean);
  });
  const c = cols.map((w) => (w ? bandCentroid(w) : NaN));
  const broken = (a: number, b: number) => Number.isFinite(c[a]) && Number.isFinite(c[b]) && !(c[a] < c[b]);
  const drop = [broken(0, 1) || broken(0, 2), broken(0, 1) || broken(1, 2), broken(1, 2) || broken(0, 2)];
  drop.forEach((d, k) => d && (cols[k] = null));
  return cols;
}

function adaptedBasis(base: Basis, cols: readonly (Float64Array | null)[]): Basis {
  // the adapted column replaces the class's own instrument (HH: the closed HH columns; the open HH ones stay, their seeds are not taken)
  const keep = base.inst.map((inst, k) => !(inst && (S3_CLASSES as readonly string[]).includes(inst) && cols[(S3_CLASSES as readonly string[]).indexOf(base.group[k])]));
  const out: Basis = { W: base.W.filter((_, k) => keep[k]), group: base.group.filter((_, k) => keep[k]), metal: base.metal.filter((_, k) => keep[k]), inst: base.inst.filter((_, k) => keep[k]) };
  cols.forEach((w, k) => {
    if (!w) return;
    out.W.push(w);
    out.group.push(S3_CLASSES[k]);
    out.metal.push(false);
    out.inst.push(null);
  });
  return out;
}

/* ------------------------------------------------------------------ S-9 (T11) */

const TOM_INDEX: Partial<Record<DrumInst, number>> = { T1: 0, T2: 1, FT: 2 };
const METAL_OF: Partial<Record<DrumInst, keyof MetalVotes>> = { HH: 'HH', HO: 'HO', RD: 'RD', 'RD.bell': 'RD', CR: 'CR', SP: 'CR', CN: 'CR' };

/** Per-onset S-9 evidence from the final fit: tom activation and template vote, metal votes, total. */
export function s9Evidence(fit: NonNullable<ClassifyResult['fit']>): { total: number; bd: number; sd: number; tom: number; tomVote: number; metal: MetalVotes; spcn: number }[] {
  return fit.h.map((h) => {
    let total = 0;
    let bd = 0;
    let sd = 0;
    let tom = 0;
    let tomIdx = 0;
    const metal: MetalVotes = { HH: 0, HO: 0, RD: 0, CR: 0 };
    let sp = 0;
    let cn = 0;
    h.forEach((v, k) => {
      total += v;
      if (fit.group[k] === 'BD') bd += v;
      if (fit.group[k] === 'SD') sd += v;
      const inst = fit.inst[k];
      const ti = inst ? TOM_INDEX[inst] : undefined;
      if (ti !== undefined) {
        tom += v;
        tomIdx += ti * v;
      }
      const m = inst ? METAL_OF[inst] : fit.group[k] === 'HH' ? 'HH' : undefined;
      if (m) metal[m] += v;
      if (inst === 'SP') sp += v;
      if (inst === 'CN') cn += v;
    });
    return { total, bd, sd, tom, tomVote: tom > 0 ? tomIdx / tom : NaN, metal, spcn: Math.max(sp, cn) };
  });
}

/**
 * Step 6 (T11b): the basis with the kit's tom columns replaced by per-take ones - seeds (toms.ts tomSeeds) grouped by
 * pitch (groupPitches), one column per group = mean of the normalised seed observations, named by groupNames with
 * votes from the group's pitch re the take's snare pitch (ratioVote: the kit's tom templates say nothing here). null (keep the basis) without seeds, or when any group mean is within cosine adaptKeepCos
 * of one of the kit's tom columns (one of the take's toms is the kit's own: a known kit; tuning A / H >= .97, D and
 * LOPO <= .92).
 */
export function tomAdaptedBasis<B extends Pick<Basis, 'W' | 'group' | 'metal' | 'inst'>>(
  base: B,
  obs: readonly ArrayLike<number>[],
  feats: readonly TomFeatures[],
  cls: readonly Pick<OnsetClass, 'present' | 'share'>[],
  cfg: DrumConfig['toms'],
): Basis | null {
  const { seeds, sdPitch } = tomSeeds(feats, cls, cfg);
  const idx = seeds.map((s, i) => (s ? i : -1)).filter((i) => i >= 0);
  if (!idx.length) return null;
  const g = groupPitches(
    idx.map((i) => feats[i].pitch),
    cfg.groups,
    cfg.minGapOct,
  );
  const means = Array.from({ length: g.count }, () => new Float64Array(obs[0].length));
  idx.forEach((i, j) => normalised(Float64Array.from(obs[i])).forEach((v, m) => (means[g.group[j]][m] += v)));
  const cols = means.map((w) => normalised(w));
  const isTom = (inst: DrumInst | null) => !!inst && (TOMS as readonly string[]).includes(inst);
  const kit = base.W.filter((_, k) => isTom(base.inst[k]));
  if (cols.some((w) => kit.some((k) => cosine(k, w) >= cfg.adaptKeepCos))) return null;
  const keep = base.inst.map((inst) => !isTom(inst));
  const votes = Array.from({ length: g.count }, (_, k) => {
    const ps = idx.filter((_, j) => g.group[j] === k).map((i) => feats[i].pitch).filter(Number.isFinite);
    return ratioVote(ps.length ? 2 ** (ps.reduce((a, p) => a + Math.log2(p), 0) / ps.length) : NaN, sdPitch, cfg.nameSdRatios);
  });
  const names = groupNames(g.count, votes);
  return {
    W: [...base.W.filter((_, k) => keep[k]), ...cols],
    group: [...base.group.filter((_, k) => keep[k]), ...cols.map((): TemplateGroup => 'other')],
    metal: [...base.metal.filter((_, k) => keep[k]), ...cols.map(() => false)],
    inst: [...base.inst.filter((_, k) => keep[k]), ...names],
  };
}

/** Take reference of an activation: refQuantile over the onsets it dominates (share >= .5), else over all totals. */
function takeRef(a: readonly number[], total: readonly number[], cfg: DrumConfig['classify']): number {
  const dom = a.filter((v, i) => total[i] > 0 && v / total[i] >= 0.5);
  return dom.length >= cfg.refMinHits ? quantileOf(dom, cfg.refQuantile) : quantileOf([...total], cfg.refQuantile);
}

/**
 * S-9 hits (T11): BD as S-3; SD as S-3 unless a tom is present and SD's share < toms.sdKeepShare; a tom (toms.ts) when
 * the tom columns hold >= toms.shareMin at >= toms.levelMinDb (none in a take where such onsets exceed toms.maxTakeShare
 * of the onsets with SD or a tom); one metal piece (cymbals.ts) on S-3 HH or on enough
 * cymbal-absorber activation. Only S-3 decisions and the final fit are read; S-3 output is not changed.
 */
export function s9Hits(
  det: OnsetDetection,
  cls: readonly OnsetClass[],
  fit: NonNullable<ClassifyResult['fit']>,
  raw: MelSpec,
  obs: readonly Float64Array[],
  p: SpecParams,
  cfg: DrumConfig,
  feats: readonly TomFeatures[],
  adaptedToms = false,
  metalFit: NonNullable<ClassifyResult['fit']> = fit,
): AnalysisDrumHit[] {
  const c = cfg.classify;
  const ev = s9Evidence(fit);
  // metal pieces from metalFit (the fit before step 6: the per-take tom columns only decide toms, BD and SD)
  const evm = metalFit === fit ? ev : s9Evidence(metalFit);
  const total = ev.map((e) => e.total);
  const cymA = evm.map((e) => e.metal.HO + e.metal.RD + e.metal.CR);
  const totalM = evm.map((e) => e.total);
  const tomRef = takeRef(ev.map((e) => e.tom), total, c);
  const cymRef = takeRef(cymA, totalM, c);
  const lvl = (v: number, ref: number, min: number) => ref > 0 && 20 * Math.log10(Math.max(v, 1e-30) / ref) >= min;
  const tomClaim = ev.map((e) => e.total > 0 && e.tom / e.total >= cfg.toms.shareMin && lvl(e.tom, tomRef, cfg.toms.levelMinDb));
  // toms play fills: when they would outnumber maxTakeShare of the take's SD-or-tom onsets, the kit's SD looks like the
  // template kit's toms (another kit), so the take keeps its SDs and gets no toms
  const nClaim = tomClaim.filter(Boolean).length;
  const nSdOrTom = cls.filter((o, i) => o.present[1] || tomClaim[i]).length;
  const tomOn = nClaim > cfg.toms.maxTakeShare * nSdOrTom ? tomClaim.map(() => false) : tomClaim;
  // on a tom onset the cymbal absorbers must also keep shareMin in the tom-adapted fit (they took the unknown tom's ring before)
  const cymShare = (e: (typeof ev)[number]) => (e.total > 0 ? (e.metal.HO + e.metal.RD + e.metal.CR) / e.total : 0);
  const metalOn = evm.map(
    (e, i) =>
      cls[i].present[2] ||
      (e.total > 0 && cymA[i] / e.total >= cfg.cymbals.shareMin && lvl(cymA[i], cymRef, cfg.cymbals.levelMinDb) && (!tomOn[i] || cymShare(ev[i]) >= cfg.cymbals.shareMin)),
  );
  const centres = melFrequencies(p.melBands + 2, p.fminHz, Math.min(p.fmaxHz, p.sr / 2)).slice(1, -1);
  const frames = det.onsets.map((o) => Math.round((o.t * p.sr) / p.hop));
  const cy = cfg.cymbals;
  const drop = highDrops(raw, centres, frames, { fminHz: cy.fminHz, dropFrames: cy.dropFrames, dropMinFrames: cy.dropMinFrames });
  const closed = cls.map((o, i) => o.present[2] && !o.present[0] && !o.present[1] && !tomOn[i] && drop[i] < cy.fastDb);
  const cosHh = cosToProfile(obs, centres, closed, cy.profileFminHz, cy.profileMinHits);
  // toms: names by relative pitch within the take
  const tomIdx = tomOn.map((on, i) => (on ? i : -1)).filter((i) => i >= 0);
  const g = groupPitches(
    tomIdx.map((i) => feats[i].pitch),
    cfg.toms.groups,
    cfg.toms.minGapOct,
  );
  const votes = Array.from({ length: g.count }, (_, k) => {
    const v = tomIdx.filter((_, j) => g.group[j] === k).map((i) => ev[i].tomVote).filter(Number.isFinite);
    return v.length ? v.reduce((a, b) => a + b, 0) / v.length : NaN;
  });
  const names = groupNames(g.count, votes);
  // per-take tom columns (step 6) that cover all `groups` toms stand for the take's toms: with nameByColumn an onset takes
  // the name of its largest one (its own pitch can be an octave off). Fewer columns: some tom had no seeds, so pitch groups.
  const nTomCols = fit.inst.filter((inst) => inst && TOM_INDEX[inst] !== undefined).length;
  const byColumn = (i: number): TomInst | undefined => {
    let best = -1;
    fit.h[i].forEach((v, k) => {
      const inst = fit.inst[k];
      if (inst && TOM_INDEX[inst] !== undefined && (best < 0 || v > fit.h[i][best])) best = k;
    });
    return best >= 0 ? (fit.inst[best] as TomInst) : undefined;
  };
  const tomName = new Map(tomIdx.map((i, j) => [i, (adaptedToms && cfg.toms.nameByColumn && nTomCols >= cfg.toms.groups && byColumn(i)) || names[g.group[j]]]));
  const hits: AnalysisDrumHit[] = [];
  cls.forEach((o, i) => {
    const t = o.t;
    if (o.present[0] && !(tomOn[i] && ev[i].bd / ev[i].total < cfg.toms.bdKeepShare)) hits.push({ t, inst: 'BD', strength: o.strength[0], confidence: o.confidence[0] });
    if (o.present[1] && !(tomOn[i] && ev[i].sd / ev[i].total < cfg.toms.sdKeepShare)) hits.push({ t, inst: 'SD', strength: o.strength[1], confidence: o.confidence[1] });
    const tn = tomName.get(i);
    if (tn) {
      const share = ev[i].tom / ev[i].total;
      const alt = TOMS.filter((x) => x !== tn).sort((a, b) => Math.abs(TOMS.indexOf(a) - TOMS.indexOf(tn)) - Math.abs(TOMS.indexOf(b) - TOMS.indexOf(tn)))[0];
      hits.push({ t, inst: tn, strength: ev[i].tom, confidence: presentConf(share, cfg.toms.shareMin), ...(c.candidatesMax > 0 ? { alts: [{ inst: alt, confidence: 0.25 }] } : {}) });
    }
    if (metalOn[i]) {
      const m = metalLabel(evm[i].metal, drop[i], cosHh[i], cy, evm[i].metal.CR > 0 ? evm[i].spcn / evm[i].metal.CR : 0);
      const conf = o.present[2] ? o.confidence[2] : presentConf(cymA[i] / evm[i].total, cy.shareMin);
      const strength = o.present[2] ? o.strength[2] : cymA[i];
      hits.push({ t, inst: m.inst, strength, confidence: conf, ...(c.candidatesMax > 0 ? { alts: [{ inst: m.alt, confidence: Math.min(0.499, conf / 2) }] } : {}) });
    }
  });
  return hits;
}

/** Step 7 evidence (ext.ts ExtEvidence) per onset: activations by kit instrument of `fit`, drop, tonal peak. */
export function extEvidence(
  fit: NonNullable<ClassifyResult['fit']>,
  raw: MelSpec,
  det: OnsetDetection,
  p: SpecParams,
  cfg: DrumConfig,
  wins: readonly { mag: Float64Array; size: number }[],
  foot: { W: readonly ArrayLike<number>[]; feet: readonly ArrayLike<number>[]; obs: readonly ArrayLike<number>[] },
): ExtEvidence[] {
  const centres = melFrequencies(p.melBands + 2, p.fminHz, Math.min(p.fmaxHz, p.sr / 2)).slice(1, -1);
  const cy = cfg.cymbals;
  const drop = highDrops(raw, centres, det.onsets.map((o) => Math.round((o.t * p.sr) / p.hop)), { fminHz: cy.fminHz, dropFrames: cy.dropFrames, dropMinFrames: cy.dropMinFrames });
  return fit.h.map((h, i) => {
    const act: ExtEvidence['act'] = {};
    let total = 0;
    h.forEach((v, k) => {
      total += v;
      const inst = fit.inst[k];
      if (inst) act[inst] = (act[inst] ?? 0) + v;
    });
    const tp = tonalPeak(wins[i].mag, wins[i].size, det.sr, cfg.ext.tonalMinHz, cfg.ext.tonalMaxHz);
    // pedal HH: share of the foot columns when they join the fit's basis (only when switched on and the table has them)
    let footShare = 0;
    if (cfg.ext.footShare > 0 && foot.feet.length) {
      const hf = solveActivations([...foot.W, ...foot.feet], foot.obs[i], cfg.classify.nmfIterations, cfg.classify.nmfBeta);
      let all = 0;
      let ft = 0;
      hf.forEach((v, k) => ((all += v), k >= foot.W.length && (ft += v)));
      footShare = all > 0 ? ft / all : 0;
    }
    return { act, total, drop: drop[i], tonal: tp.tonal, tonalHz: tp.hz, foot: footShare };
  });
}

export function classifyOnsets(det: OnsetDetection, cfg: DrumConfig = DEFAULT_DRUM_CONFIG, table: TemplateTable = DRUM_TEMPLATES, level: DrumLevel = 'S-3'): ClassifyResult {
  const t0 = performance.now();
  const c = cfg.classify;
  if (!c.nmf) {
    const onsets = classifyRules(det.onsets, det.thresholds, c);
    const ms = performance.now() - t0;
    if (level !== 'S-3') throw new Error('classify: S-9 needs nmf');
    return { hits: hitsOf(onsets, c.candidatesMax), onsets, columns: 0, refitAdded: [], adapted: [], ms: { spec: 0, nmf: ms, total: ms } };
  }
  const p = specParams(cfg);
  if (det.sr !== p.sr) throw new Error(`classify: onset sr ${det.sr} != audio.sr ${p.sr}`);
  if (!sameParams(table.params, p)) throw new Error(`classify: template table built for ${JSON.stringify(table.params)}, config needs ${JSON.stringify(p)}; run make_templates.ts`);
  const raw = melSpectrogram(det.y, p);
  const spec = c.hpss ? hpssPercussive(raw, c.hpssTimeFrames, c.hpssFreqBins) : raw;
  const obs = det.onsets.map((o) => observation(spec, o.t, p));
  const t1 = performance.now();
  let basis = basisOf(table, c);
  const fast =
    c.metalDecay || c.adapt
      ? highDecayRates(raw, det.onsets, p, { fminHz: c.decayFminHz, minMs: c.decayMinMs, maxMs: c.decayMaxMs }).map((r) => r >= c.hhMinDecayDbPerSec)
      : det.onsets.map(() => false);
  let last: { b: Basis; acts: Act[] } = { b: basis, acts: [] };
  let merge: readonly boolean[] = [];
  const acts = (b: Basis) => {
    last = { b, acts: activations(b, obs, c) };
    return mergeMetal(last.acts, merge);
  };
  if (c.metalDecay) merge = metalTakeIsHh(activations(basis, obs, c), fast, c.metalTakeFastMin, c.refMinHits) ? fast : [];
  for (let it = 0; it < c.eqRounds; it++) {
    const fit = activations(basis, obs, c);
    basis = equalised(basis, takeEq(obs, basis.W, fit.map((x) => x.h), c.eqMaxDb));
  }
  let onsets = decideNmf(det.onsets, acts(basis), c);
  let columns = basis.W.length;
  const refitAdded: S3Class[] = [];
  if (c.refit) {
    S3_CLASSES.forEach((cls, k) => {
      const conf = onsets.map((o, i) => ({ o, i })).filter(({ o }) => o.present[k] && o.present.filter(Boolean).length === 1 && o.share[k] >= c.refitShare);
      if (conf.length < c.refitMinHits) return;
      const mean = new Float64Array(p.melBands);
      for (const { i } of conf) normalised(obs[i]).forEach((v, m) => (mean[m] += v / conf.length));
      basis.W.push(normalised(mean));
      basis.group.push(cls);
      basis.metal.push(false);
      basis.inst.push(null);
      refitAdded.push(cls);
    });
    columns = basis.W.length;
    if (refitAdded.length) onsets = decideNmf(det.onsets, acts(basis), c);
  }
  let adapted: S3Class[] = [];
  if (c.adapt) {
    const kitCols = S3_CLASSES.map((cls) => basis.W.filter((_, k) => basis.inst[k] === cls));
    const centres = melFrequencies(p.melBands + 2, p.fminHz, Math.min(p.fmaxHz, p.sr / 2)).slice(1, -1);
    for (let it = 0; it < c.adaptIterations; it++) {
      const { b: lb, acts: la } = last;
      const parts = obs.map((x, i) => classParts(x, lb.W, lb.group, la[i].h, lb.metal.map((m) => m && !!merge[i]), onsets[i].share.map((sh) => sh < c.adaptSubMin)));
      const cols = adaptColumns(parts, onsets, fast, centres, c, kitCols);
      adapted = S3_CLASSES.filter((_, k) => cols[k]);
      if (!adapted.length) break;
      const b = adaptedBasis(basis, cols);
      onsets = decideNmf(det.onsets, acts(b), c);
      columns = b.W.length;
    }
  }
  const t2 = performance.now();
  const s3fit = { inst: last.b.inst, group: last.b.group, h: last.acts.map((x) => x.h) };
  let fit = s3fit;
  let hits: AnalysisDrumHit[];
  if (level === 'S-3') hits = hitsOf(onsets, c.candidatesMax);
  else {
    const wins = det.onsets.map((o) => windowMag(det.y, det.sr, o.t, cfg.toms));
    const feats = wins.map((w) => tomFeaturesOf(w, det.sr, cfg.toms));
    const tb = cfg.toms.adapt ? tomAdaptedBasis(last.b, obs, feats, onsets, cfg.toms) : null;
    if (tb) fit = { inst: tb.inst, group: tb.group, h: activations(tb, obs, c).map((x) => x.h) };
    hits = s9Hits(det, onsets, fit, raw, obs, p, cfg, feats, !!tb, s3fit);
    if (level === 'S-ext') {
      const foot = { W: last.b.W, feet: table.columns.filter((col) => col.group === 'extFoot').map((col) => col.w), obs };
      hits = extHits(hits, det.onsets.map((o) => o.t), extEvidence(s3fit, raw, det, p, cfg, wins, foot), cfg.cymbals.riseDb, cfg.ext);
    }
  }
  return { hits, onsets, columns, refitAdded, adapted, fit, ms: { spec: t1 - t0, nmf: t2 - t1, total: t2 - t0 } };
}
